import 'package:flutter/material.dart';import 'glass_card.dart';class FuturisticStatCard extends StatelessWidget{final IconData icon;final String label,value;final Color color;const FuturisticStatCard({super.key,required this.icon,required this.label,required this.value,this.color=Colors.white});@override Widget build(BuildContext c)=>Expanded(child:GlassCard(glowColor:color,padding:const EdgeInsets.all(12),child:Column(children:[Icon(icon,color:color),const SizedBox(height:6),Text(value,style:const TextStyle(color:Colors.white,fontWeight:FontWeight.w800)),Text(label,style:TextStyle(color:Colors.white.withOpacity(.55),fontSize:11))])));}